## 4. Core Components (templates)

> Each component below follows the same pattern: **props → UI → events**.  
> Replace `/* TODO */` with your own logic.

### 4.1 UI Primitives (`components/ui/`)

```tsx
// Button.tsx
import { ButtonHTMLAttributes } from 'react';
import clsx from 'clsx';

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'outline';
}

export const Button = ({
  variant = 'primary',
  className,
  ...props
}: ButtonProps) => (
  <button
    className={clsx(
      'px-4 py-2 rounded font-medium focus:outline-none focus:ring-2',
      variant === 'primary' && 'bg-indigo-600 text-white hover:bg-indigo-700',
      variant === 'secondary' && 'bg-gray-200 text-gray-800 hover:bg-gray-300',
      variant === 'outline' && 'border border-indigo-600 text-indigo-600 hover:bg-indigo-50',
      className
    )}
    {...props}
  />
);
```

```tsx
// Modal.tsx
import { Dialog } from '@headlessui/react';
import { Fragment } from 'react';

export interface ModalProps {
  open: boolean;
  onClose: () => void;
  title: string;
  children: React.ReactNode;
}

export const Modal = ({ open, onClose, title, children }: ModalProps) => (
  <Dialog as="div" open={open} onClose={onClose} className="fixed inset-0 z-50 overflow-y-auto">
    <Dialog.Overlay className="fixed inset-0 bg-black opacity-30" />
    <div className="flex items-center justify-center min-h-screen p-4">
      <Dialog.Panel className="bg-white rounded-lg shadow-xl max-w-md w-full">
        <Dialog.Title className="text-lg font-semibold p-4 border-b">{title}</Dialog.Title>
        <div className="p-4">{children}</div>
        <div className="p-4 border-t flex justify-end">
          <Button variant="outline" onClick={onClose}>Close</Button>
        </div>
      </Dialog.Panel>
    </div>
  </Dialog>
);
```

```tsx
// Toast.tsx
import { Transition } from '@headlessui/react';
import { useEffect, useState } from 'react';

export interface ToastProps {
  message: string;
  type?: 'success' | 'error' | 'info';
  duration?: number; // ms
}

export const Toast = ({ message, type = 'info', duration = 3000 }: ToastProps) => {
  const [visible, setVisible] = useState(true);
  useEffect(() => {
    const timer = setTimeout(() => setVisible(false), duration);
    return () => clearTimeout(timer);
  }, [duration]);

  return (
    <Transition show={visible} appear>
      <div
        className={`fixed bottom-4 right-4 px-4 py-2 rounded shadow-lg text-white ${
          type === 'success' ? 'bg-green-600' :
          type === 'error' ? 'bg-red-600' :
          'bg-blue-600'
        }`}
      >
        {message}
      </div>
    </Transition>
  );
};
```

### 4.2 Layout (`components/layout/`)

```tsx
// Header.tsx
import Link from 'next/link';
import { useCartStore } from '../../store/cart';
import { Button } from '../ui/Button';

export const Header = () => {
  const cartCount = useCartStore((state) => state.items.length);
  return (
    <header className="bg-white shadow">
      <div className="max-w-7xl mx-auto px-4 py-4 flex justify-between items-center">
        <Link href="/">
          <a className="text-2xl font-bold text-indigo-600">Shop</a>
        </Link>
        <nav className="space-x-4">
          <Link href="/products"><a>Products</a></Link>
          <Link href="/cart"><a>Cart ({cartCount})</a></Link>
          <Link href="/login"><a>Login</a></Link>
        </nav>
      </div>
    </header>
  );
};
```

