```tsx
// ThemeProvider.tsx
import { ThemeProvider as NextThemeProvider } from 'next-themes';
import { useEffect, useState } from 'react';

export const ThemeProvider = ({ children }: { children: React.ReactNode }) => {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);
  if (!mounted) return null;
  return <NextThemeProvider attribute="class">{children}</NextThemeProvider>;
};
```

### 4.3 Pages (`pages/`)

#### 4.3.1 Product List (`pages/products/index.tsx`)

```tsx
import { GetStaticProps } from 'next';
import { useRouter } from 'next/router';
import { ProductCard } from '../../components/widgets/ProductCard';
import { fetchProducts } from '../../lib/api';

export const getStaticProps: GetStaticProps = async () => {
  const products = await fetchProducts(); // returns array of { id, slug, title, price, image }
  return { props: { products }, revalidate: 60 };
};

export default function ProductList({ products }: { products: any[] }) {
  const router = useRouter();
  return (
    <div className="max-w-7xl mx-auto p-4 grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
      {products.map((p) => (
        <ProductCard key={p.id} product={p} onClick={() => router.push(`/products/${p.slug}`)} />
      ))}
    </div>
  );
}
```

#### 4.3.2 Product Detail (`pages/products/[slug].tsx`)

```tsx
import { GetStaticPaths, GetStaticProps } from 'next';
import { useRouter } from 'next/router';
import { fetchProductBySlug, fetchProducts } from '../../lib/api';
import { ProductImageGallery } from '../../components/widgets/ProductImageGallery';
import { Button } from '../../components/ui/Button';
import { useCartStore } from '../../store/cart';

export const getStaticPaths: GetStaticPaths = async () => {
  const products = await fetchProducts();
  const paths = products.map((p: any) => ({ params: { slug: p.slug } }));
  return { paths, fallback: 'blocking' };
};

export const getStaticProps: GetStaticProps = async ({ params }) => {
  const product = await fetchProductBySlug(params?.slug as string);
  return { props: { product }, revalidate: 60 };
};

export default function ProductDetail({ product }: { product: any }) {
  const addToCart = useCartStore((s) => s.addItem);
  return (
    <div className="max-w-7xl mx-auto p-4 flex flex-col md:flex-row gap-8">
      <ProductImageGallery images={product.images} />
      <div className="flex-1">
        <h1 className="text-3xl font-bold">{product.title}</h1>
        <p className="mt-2 text-2xl text-indigo-600">${product.price}</p>
        <p className="mt-4">{product.description}</p>
        <Button className="mt-6" onClick={() => addToCart(product)}>Add to Cart</Button>
      </div>
    </div>
  );
}
```

#### 4.3.3 Cart (`pages/cart.tsx`)

```tsx
import { useCartStore } from '../store/cart';
import { Button } from '../components/ui/Button';
import Link from 'next/link';

export default function Cart() {
  const { items, removeItem, clearCart, total } = useCartStore();
  return (
    <div className="max-w-7xl mx-auto p-4">
      <h1 className="text-2xl font-semibold mb-4">Your Cart</h1>
      {items.length === 0 ? (
        <p>Your cart is empty. <Link href="/products"><a>Continue shopping</a></Link></p>
      ) : (
        <>
          <ul className="space-y-4">
            {items.map((i) => (
              <li key={i.id} className="flex items-center justify-between">
                <div>{i.title} × {i.quantity}</div>
                <div>${(i.price * i.quantity).toFixed(2)}</div>
                <Button variant="outline" size="sm" onClick={() => removeItem(i.id)}>Remove</Button>
              </li>
            ))}
          </ul>
          <div className="mt-6 flex justify-between items-center">
            <div className="text-xl font-semibold">Total: ${total.toFixed(2)}</div>
            <Button onClick={clearCart}>Clear Cart</Button>
          </div>
          <Link href="/checkout"><a><Button className="mt-4">Proceed to Checkout</Button></a></Link>
        </>
      )}
    </div>
  );
}
```

#### 4.3.4 Checkout (`pages/checkout.tsx`)

```tsx
import { useCartStore } from '../store/cart';
import { useForm } from 'react-hook-form';
import { z } from 'zod';
import { zodResolver } from '@hookform/resolvers/zod';
import { Button } from '../components/ui/Button';
import { stripe } from '../lib/stripe';

const schema = z.object({
  name: z.string().min(1),
  email: z.string().email(),
  address: z.string().min(1),
});

export default function Checkout() {
  const { items, total } = useCartStore();
  const { register, handleSubmit, formState: { errors } } = useForm({
    resolver: zodResolver(schema),
  });

  const onSubmit = async (data: any) => {
    const session = await stripe.createCheckoutSession({
      line_items: items.map((i: any) => ({
        price_data: {
          currency: 'usd',
          product_data: { name: i.title },
          unit_amount: Math.round(i.price * 100),
        },
        quantity: i.quantity,
      })),
      mode: 'payment',
      success_url: `${window.location.origin}/success`,
      cancel_url: `${window.location.origin}/cancel`,
    });
    window.location.href = session.url;
  };

  return (
    <div className="max-w-7xl mx-auto p-4">
      <h1 className="text-2xl font-semibold mb-4">Checkout</h1>
      <form onSubmit={handleSubmit(onSubmit)} className="space-y-4">
        <input {...register('name')} placeholder="Name" className="input" />
        {errors.name && <p className="text-red-600">{errors.name.message}</p>}
        <input {...register('email')} placeholder="Email" className="input" />
        {errors.email && <p className="text-red-600">{errors.email.message}</p>}
        <textarea {...register('address')} placeholder="Address" className="input" />
        {errors.address && <p className="text-red-600">{errors.address.message}</p>}
        <Button type="submit" disabled={items.length === 0}>Pay ${total.toFixed(2)}</Button>
      </form>
    </div>
  );
}
```

#### 4.3.5 Auth Pages (`pages/auth/login.tsx`, `signup.tsx`, `forgot-password.tsx`)

```tsx
// login.tsx
import { useForm } from 'react-hook-form';
import { Button } from '../../components/ui/Button';
import { signIn } from 'next-auth/react';

export default function Login() {
  const { register, handleSubmit } = useForm();
  const onSubmit = async (data: any) => {
    await signIn('credentials', { redirect: false, ...data });
  };
  return (
    <form onSubmit={handleSubmit(onSubmit)} className="max-w-sm mx-auto p-4 space-y-4">
      <input {...register('email')} placeholder="Email" className="input" />
      <input {...register('password')} type="password" placeholder="Password" className="input" />
      <Button type="submit">Login</Button>
    </form>
  );
}
```

> Similar patterns for `signup.tsx` (create account) and `forgot-password.tsx` (reset link).

